 state,date=e.split('_')[:2];dt=f'{date[:4]}-{date[4:6]}-{date[6:]}';name={'ne':'NEBRASKA','ks':'KANSAS','tx':'TEXAS'}[state];row=cand[(cand.STATE==name)&(cand.utc_date==dt)].iloc[0];c=md['counts'][e];w=json.loads((R/f'window_{e}_h3.json').read_text());lines.append(f"|{e}|{row['High Wind']}|{row['Thunderstorm Wind']}|{w['peak_utc']}|{c['ts_cb_reports_corrected']}|{c['candidate_land']}→{c['eligible']}|{'合规' if e in md['strict_no_ts_cb'] else '仅参照'}|")
